'use strict';

const debug = require('debug')('dsr:client');
const protocol = require('./protocol');
const Base = require('sdk-base');
const is = require('is-type-of');
const assert = require('assert');
const sleep = require('mz-modules/sleep');

const ELEMENT_TYPE = protocol.ELEMENT_TYPE;

const SUBSCRIBE = 'sub';
const PUBLISHER = 'pub';
const SPLIT = '@@@@@';

function passThrough(data, cb) { cb(null, data.value); }

const DEFAULT_OPTIONS = {
  // 心跳定时检测时间间隔
  heartbeatInterval: 29000,
  // 响应超时时间
  responseTimeout: 10000,
  // 连接丢失重试时间间隔
  retryInterval: 5000,
  maxRetryInterval: 5 * 60000,
  configServerId: 'queryServerlist',
  protocol,
  serverListMgrClass: require('./server_list_mgr'),
  connectionClass: require('./connection'),
};

class DsrClient extends Base {
  get instanceId() {
    return this.options.app.config.instanceId;
  }

  get accessKey() {
    return this.options.app.config.accessKey;
  }

  get accessSecret() {
    return this.options.app.config.accessSecret;
  }

  constructor(options) {
    assert(options && options.app, '[Dsr] options.app is required');
    assert(options && options.app.antvip, '[Dsr] options.antvip is required');
    super(Object.assign({}, DEFAULT_OPTIONS, options, { initMethod: 'init' }));
    // 不再使用 humanize-ms 来支持 5s 这种格式
    assert(is.number(this.options.heartbeatInterval), '[Dsr] options.heartbeatInterval should be a number');
    assert(is.number(this.options.responseTimeout), '[Dsr] options.responseTimeout should be a number');
    assert(is.number(this.options.retryInterval), '[Dsr] options.retryInterval should be a number');
    assert(is.number(this.options.maxRetryInterval), '[Dsr] options.maxRetryInterval should be a number');

    this._isReady = false;
    this._isClosed = false;
    this._connection = null;
    this._requestQueue = [];
    this._configs = new Map();
    this._protocol = this.options.protocol;
    this._serverListManager = new this.options.serverListMgrClass(this.options);
    // connection 连续初始化失败重试次数. 默认是1.
    this._connCreateRetryTime = 1;

    this.on('all', data => { this._update(data); });
    this.on('connection', () => { this._registerAll(); });
    this.on('connection_close', meta => {
      this._handleConnectionClose(meta).catch(err => { this.emit('error', err); });
    });
    this.ready(err => { this._isReady = !err; });
    this._serverListManager.on('error', err => { this.error(err); });
    this._serverListManager.on('config_servers_update', val => { this._configServersUpdate(val); });
    this._serverListManager.on('no_server_available', () => { this.emit('no_server_available'); });
  }

  get logger() {
    return this.options.logger;
  }

  async init() {
    await this._serverListManager.ready();
    try {
      await this._createConnection();
    } catch (err) {
      // 没 ready 前先 warning，会尝试重连
      this.logger.warn(err);
    }
    this._requestLoop();
  }

  subscribe(reg, listener) {
    reg = this.normalizeReg(reg);
    const key = this._formatSubKey(reg);
    let registion = this._configs.get(key);
    if (!registion) {
      registion = this.createSubRegistion(reg);
      this._configs.set(key, registion);
      this._addRequest(registion);
      // 否则注册监听事件
    } else if (registion.value) {
      // 如果已经存在并且有值，则直接返回
      process.nextTick(() => {
        listener(registion.value);
      });
    }
    // 注: 这里容易导致同一个 key 被注册多次
    this.on(key, listener);
    return this;
  }

  createSubRegistion(reg) {
    const registion = Object.assign({
      appName: this.options.appName,
      value: null,
      revision: -1,
      type: SUBSCRIBE,
    }, reg);

    registion.elementtype = reg.elementtype || ELEMENT_TYPE.SUBSCRIBER; // 默认返回列表.
    registion.name = this._formatSubKey(registion);
    // 增加重试次数
    registion.retryTime = 0;
    registion.instanceId = this.instanceId;
    registion.accessKey = this.accessKey;
    registion.accessSecret = this.accessSecret;
    return registion;
  }

  unSubscribe(reg, listener) {
    reg = this.normalizeReg(reg);
    const key = this._formatSubKey(reg);
    if (!listener) {
      this.removeAllListeners(key);
    } else {
      this.removeListener(key, listener);
    }
    return this;
  }

  handleRegResult(config, result) {
    const elements = result && result.elements;
    let message = null;
    if (elements) {
      // 只有确定返回了 element 才进行判断.
      for (const element of elements) {
        // 只有返回了 包含指定消息的 element, 才说明服务端订阅成功.
        if (element && element.clientId && element.dataId) {
          message = element;
          break;
        }
      }
    }
    if (!message) {
      const err = new Error(`[Dsr] register (dataId: ${config.dataId}, groupId: ${config.groupId}) error`);
      err.name = 'DsrRegisterError';
      err.connname = this._connection.name;
      err.result = result;
      err.time = Date.now();
      if (config.retryTime < 100) {
        err.retry = true;
        err.retryTime = config.retryTime++;
      }
      throw err;
    } else {
      // 重置重试次数
      config.retryTime = 0;
    }
  }

  async _handleRequestError(err, req) {
    if (err.retry) {
      // 默认立马重试
      this._addRequest(req, true);
      this.logger.warn(err);
      return;
    }
    throw err;
  }

  handlePacket(hostname, data) {
    const elements = data.data && data.data.elements || [];
    let element;
    for (const elem of elements) {
      if (elem.dataId && elem.groupId && elem.data) {
        element = elem;
        break;
      }
    }

    if (!element) {
      this.logger.warn(`[antfin.dsr:client] conn request(${hostname}) error.`);
      return;
    }

    const dataId = element.dataId;
    const revision = element.revision && element.revision.revision || 0;

    let groupId = element.groupId || null;
    // 订阅的时候如果传入了 instanceId，这里返回的 groupId 也是包含 instanceId 的，例如：SOFA@8LFHHIA4ZPEX
    if (groupId && this.instanceId && element.groupId.endsWith(`@${this.instanceId}`)) {
      groupId = groupId.slice(0, groupId.lastIndexOf('@'));
    }

    const key = this._formatSubKey({
      dataId,
      groupId,
      type: SUBSCRIBE,
    });

    debug('configs %s', key);
    const config = this._configs.get(key);

    if (!config) return;

    if (element.isZip || config.elementtype === ELEMENT_TYPE.MULTISUBSCRIBER) {
      element.data = element.data[0] || {};
    }
    // 触发 all 事件，让数据变化可监控
    this.emit('all', {
      dataId,
      groupId,
      revision,
      value: element.data,
      hostname,
      type: SUBSCRIBE,
    });
  }

  register(reg) {
    return this.publish(reg);
  }

  publish(reg) {
    reg.dataId = reg.dataId || reg.interfaceName;
    reg = Object.assign({
      clientId: protocol.getClientId(reg.dataId),
    }, reg);

    reg = this.normalizeReg(reg);
    const key = this._formatPubKey(reg);
    let registion = this._configs.get(key);
    if (!registion) {
      registion = this._createPubRegistion(reg);
      this._configs.set(key, registion);
    } else {
      // 如果发布的内容完全一致，忽略掉
      if (registion.publishData === reg.publishData) {
        return;
      }
      registion.publishData = reg.publishData;
    }
    this._addRequest(registion);
    return this;
  }

  _createPubRegistion(reg) {
    reg.instanceId = this.instanceId;
    reg.accessKey = this.accessKey;
    reg.accessSecret = this.accessSecret;

    return Object.assign({
      appName: this.options.appName,
      publishData: reg.publishData,
      type: PUBLISHER,
    }, reg);
  }

  unRegister(reg) {
    return this.unPublish(reg);
  }

  unPublish(reg) {
    reg = Object.assign({
      clientId: protocol.getClientId(reg.dataId),
      unregister: true,
    }, reg);

    reg = this.normalizeReg(reg);
    const key = this._formatPubKey(reg);
    const registion = this._configs.get(key);
    if (!registion) {
      return this;
    }
    registion.publishData = null;
    registion.unregister = reg.unregister;
    this._addRequest(registion);
    this._configs.delete(key);
    return this;
  }

  close() {
    this._isClosed = true;
    this._serverListManager.close();
    if (!this._connection) {
      return Promise.resolve();
    }
    return this._connection.close()
      .then(() => {
        this.emit('close');
        this.emit('new_request_or_close');
      });
  }

  error(err) {
    if (this._isClosed || !err) {
      return;
    }
    this.emit('error', err);
  }

  async _requestLoop() {
    while (!this._isClosed) {
      // 如果 queue 为空，等待有新的请求
      if (!this._requestQueue.length) {
        await this.await('new_request_or_close');
      }
      if (this._isClosed) {
        return;
      }
      const req = this._requestQueue.pop();
      try {
        await this._sendRequest(req);
      } catch (err) {
        try {
          await this._handleRequestError(err, req);
        } catch (criticalErr) {
          if (this._connection) {
            await this._connection.close(criticalErr);
          } else {
            this.error(criticalErr);
          }
        }
      }
    }
  }

  normalizeReg(reg) {
    return Object.assign({
      enableSnapshot: this.options.enableSnapshot,
      groupId: 'SOFA',
    }, reg);
  }

  _addRequest(req, immediate = false) {
    // 推到栈顶 or 栈尾
    if (immediate) {
      this._requestQueue.unshift(req);
    } else {
      this._requestQueue.push(req);
    }
    this.emit('new_request_or_close', req);
  }

  _registerAll() {
    for (const reg of this._configs.values()) {
      this._addRequest(reg);
    }
  }

  async _createConnection() {
    if (this._isClosed && this._connection) {
      return;
    }
    const address = this._serverListManager.randomSelect();
    if (!address) {
      const err = new Error('[Dsr] No configserver available');
      err.name = 'DsrNoProviderError';
      throw err;
    }

    const hostname = address.hostname;
    const conn = this._connection = new this.options.connectionClass({
      hostname,
      port: address.port || this.options.defaultPort,
      heartbeatInterval: this.options.heartbeatInterval,
      responseTimeout: this.options.responseTimeout,
      protocol: this.options.protocol,
      concurrent: this.options.concurrent, // 如果设置太大, 可能会导致服务端的线程池满了.
    });
    conn.once('close', () => {
      this._connection = null;
      this.emit('connection_close', conn._meta);
    });
    conn.on('heartbeat', meta => { this.emit('connection_heartbeat', meta); });
    conn.on('request', req => { this.handlePacket(hostname, req); });
    debug('create connections %s', address.host);
    await conn.ready();
    debug('create connections ready');
    // ready 以后再监听 error 事件，避免重复的错误处理
    conn.once('error', err => { this.error(err); });
    this.emit('connection', { name: conn.name });

    // 如果成功创建
    this._connCreateRetryTime = 1;
  }

  async _handleConnectionClose({ host, port }) {
    // 清空 queue
    this._requestQueue = [];
    if (this._isClosed) {
      return;
    }
    this._serverListManager.adjustDownWeight(host);
    this._connCreateRetryTime++;
    const interval = Math.min(this._connCreateRetryTime * this.options.retryInterval, this.options.maxRetryInterval);
    this.logger.warn('[Dsr] configserver connect => %s:%s closed, try to reconnect in %d(ms) later', host, port, interval);
    await sleep(interval);
    await this._createConnection();
  }

  async _sendRequest(req) {
    if (!this._connection) {
      await this.await('connection');
    }
    const conn = this._connection;
    const { dataId, groupId, type = SUBSCRIBE } = req;
    const protocol = this._protocol;
    const key = this._formatKey(req);

    debug('send %s request %s:%s, %d in queue', type, dataId, groupId, this._requestQueue.length);
    let appContent;
    if (type === SUBSCRIBE) {
      const reg = Object.assign({
        clientId: key,
        accessKey: this.options.accessKey,
        tenantId: this.options.tenantId,
        appName: this.options.appName,
      }, req);
      appContent = protocol.createSubscriberRegRequest(reg);
    } else {
      const reg = Object.assign({
        clientId: conn.clientId,
        accessKey: this.options.accessKey,
        tenantId: this.options.tenantId,
        appName: this.options.appName,
      }, req);
      appContent = protocol.createPublisherRegRequest(reg);
    }

    const res = await new Promise((resolve, reject) => {
      conn.sendRequest(appContent, (err, data) => {
        if (err) {
          reject(err);
        } else {
          resolve(data);
        }
      });
    });
    this.handleRegResult(req, res);
  }

  _configServersUpdate(list) {
    // 如果当前连接地址不在新的地址列表中，断开重连
    if (this._connection && list && list.length &&
      list.every(item => item.hostname !== this._connection.hostname)) {
      this._connection.close();
    }
    this.emit('config_servers_update', list);
  }

  _update(data) {
    if (!data) {
      return;
    }

    const key = this._formatKey(data);
    debug('update %s, data %j', key, data);
    let registion = this._configs.get(key);
    if (!registion) {
      registion = this.createSubRegistion(data);
      this._configs.set(key, registion);
    }

    // let oldRevision = registion.revision;
    const newRevision = data.revision || 0;

    // 考虑到 Dsr 的主要用途还是 rpc 服务寻址，所以默认还是转换为 Url，通过 rawData 参数来判断是否转换
    const convertValue = passThrough;
    convertValue.call(this, data, (err, value) => {
      if (err) {
        return this.error(err);
      }
      registion.value = value;
      registion.revision = newRevision;
      this.emit(key, value, data.hostname);
    });
  }

  _formatKey(reg) {
    let key;
    if (reg.type === PUBLISHER) {
      key = this._formatPubKey(reg);
    }
    key = this._formatSubKey(reg);
    return key;
  }

  _formatSubKey(reg) {
    debug('formatSubKey %j', reg);
    return formatKey(reg.dataId, reg.groupId, SUBSCRIBE, SPLIT);
  }

  _formatPubKey(reg) {
    return formatKey(reg.dataId, reg.groupId, PUBLISHER, SPLIT);
  }
}

function formatKey(dataId, groupId, type, split) {
  const strs = [ dataId, groupId, type ];
  return strs.join(split);
}

module.exports = DsrClient;
